/**
 * GENERATED FILE PRODUCER — writes lib/geometry/__fixtures__/phase16-surface-litres-pin.json: the litres of
 * the 102 Phase 16 test boards (`phase16SurfaceBoards`, lib/geometry/__fixtures__/phase16-boards.ts) as plan
 * 16-15 left them — every rail setting fading, a wing still moving the whole section in with the outline and a
 * rail wider than its room still cut off at the stringer — BEFORE a wing became a step in the outline only
 * (D-33) and the tips stopped flipping (D-34, plan 16-16). The output is generated and must never be
 * hand-edited.
 *
 *   npx --no-install tsx --tsconfig ./tsconfig.json scripts/extract-phase16-surface-litres-pin.ts
 *
 * run from the repository root. Like the two Phase 16 pins before it, it is a record of the code as it stood, so
 * it REFUSES to run once `lib/geometry/volume.ts` exports `SMOOTH_SURFACE_FADE`: from then on the figures it
 * would write are the new rule's own, and the pin would prove nothing. It ran exactly once. (Nothing in
 * package.json — `--no-install` means npx can only run the tsx already in node_modules. No database is
 * involved.)
 *
 * Each figure is `summarizeDesign(fields).volumeLitres.toPrecision(17)`, a string, so the test compares
 * every digit a double holds.
 */
import { existsSync, writeFileSync } from "node:fs";
import path from "node:path";
import { phase16SurfaceBoards } from "@/lib/geometry/__fixtures__/phase16-boards";
import { summarizeDesign } from "@/lib/geometry/design";
import * as volume from "@/lib/geometry/volume";

const OUTPUT = path.resolve(process.cwd(), "lib/geometry/__fixtures__/phase16-surface-litres-pin.json");

function main() {
  if (!existsSync(path.resolve(process.cwd(), "lib/geometry/volume.ts"))) {
    throw new Error("Run this from the repository root (lib/geometry/volume.ts not found here).");
  }
  if ("SMOOTH_SURFACE_FADE" in volume) {
    throw new Error("the pin records 16-15's litres from before the wing and tip rule — it is never re-run");
  }
  const litres: Record<string, string> = {};
  for (const board of phase16SurfaceBoards()) {
    litres[board.label] = summarizeDesign(board.fields).volumeLitres.toPrecision(17);
  }
  const provenance =
    "GENERATED by scripts/extract-phase16-surface-litres-pin.ts from the app as plan 16-15 left it, before the " +
    "wing and tip rule (phase16SurfaceBoards, summarizeDesign, toPrecision(17)) — never hand-edit, never re-run";
  writeFileSync(OUTPUT, `${JSON.stringify({ provenance, litres }, null, 2)}\n`);
  for (const [label, value] of Object.entries(litres)) console.log(`${label}: ${Number(value).toFixed(4)} L`);
  console.log(`wrote ${path.relative(process.cwd(), OUTPUT)} (${Object.keys(litres).length} boards)`);
}

try {
  main();
} catch (error: unknown) {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
}
